import React from 'react';

import { Link } from 'react-router-dom';

import HikingBadge from '@apps/Hiking/@components/HikingBadge';
import { getUserPositionsStat } from '@apps/Hiking/@services/hikingWithFriend.service';
import { IBaseHiking } from '@apps/Hiking/@types/hikingList.types';
import { IHikingPosition } from '@apps/Hiking/@types/hikingPositionsAndVacancies.types';
import { IHikingUserPositionStat } from '@apps/Hiking/@types/hikingWithFriend.types';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohCollapsible from '@ui-kit/Collapsible';
import PohCollapsibleIcon from '@ui-kit/Collapsible/PohCollapsibleIcon';
import PohList from '@ui-kit/List';

interface IUserPositionsProps {
  id_user: number;
}

interface IAggregateUserPositions {
  position: IHikingPosition;
  hikingList: IBaseHiking[];
  first: Date;
  last: Date;
}

const UserPositions: React.FC<IUserPositionsProps> = ({ id_user }) => {
  const [err, setErr] = React.useState<Error>();
  const [isLoading, setIsLoading] = React.useState(true);
  const [data, setData] = React.useState<IHikingUserPositionStat[]>([]);

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const dt = await getUserPositionsStat({ id_user });
        setData(dt);
      } catch (error) {
        setErr(error as Error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, [id_user]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  const aggregatedPositions = Object.values(
    data.reduce<{ [key: IHikingPosition['id']]: IAggregateUserPositions }>((acc, val) => {
      if (!acc[val.position.id]) {
        acc[val.position.id] = {
          position: { ...val.position },
          first: val.hiking.start,
          last: val.hiking.finish,
          hikingList: [],
        } satisfies IAggregateUserPositions;
      }
      acc[val.position.id].hikingList.push(val.hiking);
      if (val.hiking.start < acc[val.position.id].first) {
        acc[val.position.id].first = val.hiking.start;
      }
      if (val.hiking.finish > acc[val.position.id].last) {
        acc[val.position.id].last = val.hiking.finish;
      }

      return acc;
    }, {}),
  );

  if (!aggregatedPositions.length) return null;

  return (
    <PohCollapsible
      activatorComponent={(open) => (
        <h4 className="d-flex align-items-center">
          <PohCollapsibleIcon open={open} className="me-1" />
          Должности{' '}
          <small className="ms-2">
            <PohBadge as="small" variant={BadgeVariant.Success}>
              <small>{data.length}</small>
            </PohBadge>
          </small>
        </h4>
      )}
    >
      {aggregatedPositions.map((pos) => {
        return (
          <PohCollapsible
            key={pos.position.id}
            activatorComponent={(open) => (
              <strong title={pos.position.description} className="d-flex align-items-center">
                <PohCollapsibleIcon open={open} className="me-1" />
                {pos.position.name}{' '}
                <small className="ms-2">
                  <PohBadge as="small" variant={BadgeVariant.Success}>
                    <small>{pos.hikingList.length}</small>
                  </PohBadge>
                </small>
              </strong>
            )}
          >
            <PohList
              data={pos.hikingList.map((h) => {
                return {
                  key: h.id,
                  as: Link,
                  to: `/hiking/${h.id}`,
                  children: <HikingBadge hiking={h} />,
                };
              })}
            />
          </PohCollapsible>
        );
      })}
    </PohCollapsible>
  );
};

export default UserPositions;
