import React from 'react';

import { useNavigate } from 'react-router-dom';

import { HikingBadgeOneLine } from '@apps/Hiking/@components/HikingBadge';
import ObstacleCategoryBadge from '@apps/Obstacles/components/ObstacleCategoryBadge/ObstacleCategoryBadge';
import PageLoader from '@components/PageLoader';
import { dateRangeToLocaleString } from '@helpers/dateHelper';
import { formatAltitude } from '@helpers/formatHelper';
import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';
import PohCollapsible from '@ui-kit/Collapsible';
import PohCollapsibleIcon from '@ui-kit/Collapsible/PohCollapsibleIcon';
import PohList, { IPohListItem } from '@ui-kit/List';

import UserObstaclesPassesStat from './UserObstaclesPassesStat';
import UserObstaclesPeaksStat from './UserObstaclesPeaksStat';
import { getObstaclesForUserAsync } from '../../Obstacles/@services/obstacles.service';
import { IObstacleForUser, ObstacleType } from '../../Obstacles/@types/obstacles.types';

interface IUserObstaclesProps {
  id_user: number;
}

const UserObstacles: React.FC<IUserObstaclesProps> = ({ id_user }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [data, setData] = React.useState<IObstacleForUser[]>([]);
  const navigate = useNavigate();
  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const dt = await getObstaclesForUserAsync({ id_user });
        setData(dt);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, [id_user]);

  if (isLoading) return <PageLoader />;

  const {
    passes: passesMap,
    peaks: peaksMap,
    poi: poiMap,
  } = data.reduce<{
    passes: Record<number, IObstacleForUser[]>;
    peaks: Record<number, IObstacleForUser[]>;
    poi: Record<number, IObstacleForUser[]>;
  }>(
    (acc, val) => {
      if (val.type === ObstacleType.Pass) {
        if (!acc.passes[val.id]) acc.passes[val.id] = [];
        acc.passes[val.id].push(val);
      }
      if (val.type === ObstacleType.Peak) {
        if (!acc.peaks[val.id]) acc.peaks[val.id] = [];
        acc.peaks[val.id].push(val);
      }
      if (val.type === ObstacleType.Poi) {
        if (!acc.poi[val.id]) acc.poi[val.id] = [];
        acc.poi[val.id].push(val);
      }
      return acc;
    },
    {
      peaks: {},
      passes: {},
      poi: {},
    },
  );

  const passes = Object.values(passesMap);
  const peaks = Object.values(peaksMap);
  const poi = Object.values(poiMap);

  const mapToPohListItem = (obstacleVisits: IObstacleForUser[]): IPohListItem => {
    const h = obstacleVisits[0];
    return {
      key: h.id,
      onClick: () => navigate(`/hiking/${h.hiking.id}/obstacles/${h.id}/${h.id_hiking_obstacle}`),
      action: true,
      children: (
        <div className="w-100">
          <strong className="list-item-heading d-block m-0">
            {h.name}{' '}
            {obstacleVisits.length > 1 && (
              <strong className="text-success">
                <small className="bg-light">×&thinsp;{obstacleVisits.length}</small>
              </strong>
            )}
            <small className="float-end">
              {formatAltitude(h.altitude)}
              &nbsp;
              <ObstacleCategoryBadge category={h.category} />
            </small>
          </strong>

          {/* <small className="d-block text-muted">{h.description}</small> */}
          <div className="d-flex justify-content-between align-items-center">
            <small className="d-block text-info">
              {dateRangeToLocaleString(h.date_in, h.date_out)}
            </small>
            <HikingBadgeOneLine className="flex-row-reverse gap-1" hiking={h.hiking} />
          </div>
        </div>
      ),
    };
  };

  return (
    <>
      {peaks.length > 0 && (
        <div className="mb-3">
          <PohCollapsible
            open
            id="peaks"
            activatorComponent={(open) => (
              <h4 className="d-flex align-items-center">
                <PohCollapsibleIcon open={open} className="me-1" />
                Вершины{' '}
                <small className="ms-2">
                  <PohBadge as="small" variant={BadgeVariant.Success}>
                    <small>{peaks.length}</small>
                  </PohBadge>
                </small>
              </h4>
            )}
          >
            <UserObstaclesPeaksStat obstacles={peaks.flat()} />
            <h5 className="mt-2">Все вершины</h5>
            <PohList data={peaks.map(mapToPohListItem)} />
          </PohCollapsible>
        </div>
      )}
      {passes.length > 0 && (
        <div className="mb-3">
          <PohCollapsible
            open
            id="passes"
            activatorComponent={(open) => (
              <h4 className="d-flex align-items-center">
                <PohCollapsibleIcon open={open} className="me-1" />
                Перевалы{' '}
                <small className="ms-2">
                  <PohBadge as="small" variant={BadgeVariant.Success}>
                    <small>{passes.length}</small>
                  </PohBadge>
                </small>
              </h4>
            )}
          >
            <UserObstaclesPassesStat obstacles={passes.flat()} />
            <h5 className="mt-2">Все перевалы</h5>
            <PohList data={passes.map(mapToPohListItem)} />
          </PohCollapsible>
        </div>
      )}
      {poi.length > 0 && (
        <div className="mb-3">
          <h4>Интересные места</h4>
          <PohList data={poi.map(mapToPohListItem)} />
        </div>
      )}
    </>
  );
};

export default UserObstacles;
